@MainActor extension NikClient {
    public static func preview() -> NikClient { preview(control: true) }
    public static func preview(control: Bool, connection: ConnectionState = .live) -> NikClient {
        let client = NikClient(); client.isPreview = true; client.connection = connection
        client.seat = Seat(.object(["id": .string("iphone"), "name": .string("iPhone"), "kind": .string("device"), "control": .bool(control)]))
        client.extensionVersion = "0.2.0"
        client.fleet = PreviewFixtures.fleet; client.history = PreviewFixtures.history
        for row in client.fleet.rows {
            let snapshot = PreviewFixtures.conversation
            var state = ConversationState(id: row.id)
            state.clientID = snapshot.client; state.items = snapshot.items; state.meta = snapshot.meta
            state.meta.raw["provider"] = .string(row.provider.rawValue); state.meta.raw["label"] = .string(row.label)
            state.status = row.status; state.stats = snapshot.stats; state.configuration = snapshot.configuration
            if row.status != .waiting { state.items.removeAll { $0.kind == "permission" } }
            if ![.working, .waiting].contains(row.status) {
                state.stats.raw["running"] = .bool(false)
                state.items = state.items.map { original in
                    var item = original; item.raw["streaming"] = .bool(false)
                    if item.kind == "tool" { item.raw["status"] = .string("done") }; return item
                }
                state.items.append(TranscriptItem(.object(["id": .string("preview-final"), "kind": .string("result"), "isError": .bool(row.status == .error), "text": .string(row.status == .error ? "The voice model could not be built. Retry on the laptop." : "Completed."), "durationMs": .number(21000)])))
            }
            if row.provider == .codex {
                state.meta.raw["model"] = .string("gpt-6")
                if row.status == .working { state.meta.raw["usingMac"] = .object(["since": .number(1795161540000), "title": .string("Reviewing Xcode build results")]) }
            }
            state.queue = snapshot.queue; state.dropped = snapshot.dropped; state.initialized = true; state.connection = connection
            state.pr.snapshot = PreviewFixtures.pr; state.pr.url = PreviewFixtures.pr.url ?? ""
            state.report.report = PreviewFixtures.report; state.report.isStale = false
            client.conversationByID[row.id] = state
        }
        client.selectedConversationID = "claude-1"
        client.terminal.terminals = [PreviewFixtures.terminal]; client.terminal.selectedID = "term1"
